import{_ as i,o as a,c as e,a5 as n}from"./chunks/framework.kcd3e0J6.js";const l="/study/images/compilers/llvm-ir-and-ssa.svg",g=JSON.parse('{"title":"LLVM IRとSSA — 分岐で選ばれる値を追う","description":"","frontmatter":{"title":"LLVM IRとSSA — 分岐で選ばれる値を追う","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"compilers","summary":"LLVM IRの基本ブロックと制御フローを読み、SSAの値が分岐とphiを通じてどうつながるかを調べる。","aliases":["LLVM","LLVM IR","中間表現","IR","SSA","静的単一代入","phi","φ","CFG","制御フローグラフ","基本ブロック","mem2reg"],"verification":"LLVM 14.0.6でIRのアセンブル・検証・実行とClangのIR出力を確認し、LLVMの言語仕様に照合（2026-11-06）"}},"headers":[],"relativePath":"compilers/llvm-ir-and-ssa.md","filePath":"compilers/llvm-ir-and-ssa.md"}'),t={name:"compilers/llvm-ir-and-ssa.md"};function p(h,s,k,r,o,d){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="llvm-irとssa-—-分岐で選ばれる値を追う" tabindex="-1">LLVM IRとSSA — 分岐で選ばれる値を追う <a class="header-anchor" href="#llvm-irとssa-—-分岐で選ばれる値を追う" aria-label="Permalink to &quot;LLVM IRとSSA — 分岐で選ばれる値を追う&quot;">​</a></h1><p>ソース上の変数に二つの分岐から別々の値を入れる場合、最適化では、合流後に使う値がどちらの経路から来たかを調べます。**LLVM IR（Intermediate Representation、中間表現）**では、命令を実行する順序と、値を作る命令から値を使う命令へのつながりを、型付き命令で表せます。テキスト形式の <code>.ll</code> は人が読める表現で、対応するバイナリ形式をビットコードと呼びます。<a href="https://llvm.org/docs/LangRef.html#abstract" target="_blank" rel="noreferrer">LLVM IRの概要</a> · <a href="/study/compilers/tokens-ast-and-type-checking.html">トークン・AST・型検査</a></p><h2 id="基本ブロックと分岐" tabindex="-1">基本ブロックと分岐 <a class="header-anchor" href="#基本ブロックと分岐" aria-label="Permalink to &quot;基本ブロックと分岐&quot;">​</a></h2><p>次のC++関数は、<code>keep</code> の値で異なる計算をして、その結果を2倍します。<code>unsigned</code> は32ビットの環境を想定します。</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">extern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;C&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> unsigned</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> choose_offset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">bool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> keep, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">unsigned</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> base) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    unsigned</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> offset;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (keep) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        offset </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> base </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">u</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        offset </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> base </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">u</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> offset </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">u</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>LLVM IRで、関数内の命令をまとめる単位が**基本ブロック（basic block）**です。ブロック内は先頭から順に進み、末尾の命令で次のブロックに進むか、関数から戻るかを決めます。<code>br</code> や <code>ret</code> が末尾を決める終端命令です。どのブロックからどこへ進めるかを矢印で結んだ図が <strong>CFG（制御フローグラフ）</strong> です。<a href="https://llvm.org/docs/LangRef.html#functions" target="_blank" rel="noreferrer">LLVM IRの関数と基本ブロック</a> · <a href="https://llvm.org/docs/LangRef.html#terminator-instructions" target="_blank" rel="noreferrer">終端命令</a></p><figure class="study-figure"><img src="`+l+`" alt="entryからkeepの値でtake_upまたはtake_downへ分岐する。take_upがup、take_downがdownを定義する。joinのphiは直前のブロックに対応する値を選んでoffsetを定義する。" width="760" height="352" loading="lazy"><figcaption>合流点では、どちらの矢印を通って来たかで選ばれる値が変わります。<a href="/study/images/compilers/llvm-ir-and-ssa.svg" target="_blank" rel="noopener noreferrer">制御フローグラフを拡大</a></figcaption></figure><h2 id="ssaで合流点に値を渡す" tabindex="-1">SSAで合流点に値を渡す <a class="header-anchor" href="#ssaで合流点に値を渡す" aria-label="Permalink to &quot;SSAで合流点に値を渡す&quot;">​</a></h2><p>**SSA（Static Single Assignment、静的単一代入）**では、各SSA値の定義箇所が一つです。上の関数に対応する手書きのIRでは、C++の <code>offset</code> に入る候補に <code>%up</code> と <code>%down</code> という別々の名前を付けます。<code>%keep</code> や <code>%base</code> のような関数引数も、IRでは値として使えます。<a href="https://llvm.org/docs/LangRef.html" target="_blank" rel="noreferrer">LLVM IRの言語仕様</a></p><div class="language-llvm vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">llvm</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>define i32 @choose_offset(i1 %keep, i32 %base) {</span></span>
<span class="line"><span>entry:</span></span>
<span class="line"><span>  br i1 %keep, label %take_up, label %take_down</span></span>
<span class="line"><span></span></span>
<span class="line"><span>take_up:</span></span>
<span class="line"><span>  %up = add i32 %base, 4</span></span>
<span class="line"><span>  br label %join</span></span>
<span class="line"><span></span></span>
<span class="line"><span>take_down:</span></span>
<span class="line"><span>  %down = sub i32 %base, 1</span></span>
<span class="line"><span>  br label %join</span></span>
<span class="line"><span></span></span>
<span class="line"><span>join:</span></span>
<span class="line"><span>  %offset = phi i32 [ %up, %take_up ], [ %down, %take_down ]</span></span>
<span class="line"><span>  %result = mul i32 %offset, 2</span></span>
<span class="line"><span>  ret i32 %result</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>phi</code> は、直前に通ったブロックに対応する値を選びます。<code>take_up</code> からなら <code>%up</code>、<code>take_down</code> からなら <code>%down</code> です。SSAの規則では、各入力値を使う地点は、対応する先行ブロックから合流点へ入る<strong>辺</strong>にあるとみなします。その経路で用意できる値を渡し、<code>phi</code> が合流後に使う <code>%offset</code> を定義します。例えば <code>%base</code> が10なら、真の経路で <code>(10 + 4) * 2 = 28</code>、偽の経路で <code>(10 - 1) * 2 = 18</code> を返します。<a href="https://llvm.org/docs/LangRef.html#phi-instruction" target="_blank" rel="noreferrer">LLVMのphi命令の仕様</a></p><p>ループでは、同じ命令を通るたびに異なる値を得ることがあります。SSAの「一つ」は、コードに書かれた定義箇所の数です。ループ先頭の <code>phi</code> には、初回の入口から渡す値と、ループ末尾から戻ったときに渡す値を指定できます。<a href="https://llvm.org/docs/LoopTerminology.html#loop-definition" target="_blank" rel="noreferrer">LLVMのループ表現</a></p><h2 id="メモリに置いた変数とssa値" tabindex="-1">メモリに置いた変数とSSA値 <a class="header-anchor" href="#メモリに置いた変数とssa値" aria-label="Permalink to &quot;メモリに置いた変数とSSA値&quot;">​</a></h2><p>LLVM IRでは、<code>alloca</code> で関数内の領域を取り、<code>store</code> で書いて <code>load</code> で読み出す形も使えます。一つのアドレスに何回も書けます。アドレスを表すSSA値の定義は一つで、メモリの中身は書き換えられます。<code>mem2reg</code> は、アドレスを関数外に渡さず直接読み書きするローカル変数など、条件を満たす領域をSSA値に変え、必要な合流点に <code>phi</code> を置きます。<a href="https://llvm.org/docs/tutorial/MyFirstLanguageFrontend/LangImpl07.html#memory-in-llvm" target="_blank" rel="noreferrer">LLVMの可変変数とmem2reg</a></p><h2 id="irを検証し、clangの出力と見比べる" tabindex="-1">IRを検証し、Clangの出力と見比べる <a class="header-anchor" href="#irを検証し、clangの出力と見比べる" aria-label="Permalink to &quot;IRを検証し、Clangの出力と見比べる&quot;">​</a></h2><p>手書きのIRを <code>choose-offset.ll</code> として保存し、LLVMのツールを使える端末で実行します。<code>llvm-as</code> はテキストIRをビットコードに変換し、<code>opt</code> の <code>verify</code> パスはIRの整合性を検査します。例えば <code>phi</code> から一方の先行ブロックの組を消すと、構造の不整合を検出できます。<a href="https://llvm.org/docs/CommandGuide/llvm-as.html" target="_blank" rel="noreferrer">llvm-asの仕様</a> · <a href="https://llvm.org/docs/CommandGuide/opt.html" target="_blank" rel="noreferrer">optの仕様</a></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">llvm</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">as choose</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">offset.ll </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">o choose</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">offset.bc</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">opt </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">passes</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">verify </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">disable-output</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> choose</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">offset.bc</span></span></code></pre></div><p>C++の例を <code>choose-offset.cpp</code> として保存すると、Clangが生成したIRも読めます。最適化を有効にすると、この例のような分岐は <code>select</code> などを使う形に変わる場合があります。出力を読むときは、コンパイラの版と最適化設定をそろえます。<a href="https://clang.llvm.org/docs/Toolchain.html#clang" target="_blank" rel="noreferrer">ClangのLLVM IR出力</a> · <a href="/study/runtime/cpp-internals/optimization-and-ub.html">コンパイラ最適化と未定義動作</a></p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">clang</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">++</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">std</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">+17</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">S </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">emit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">llvm </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">O0 choose</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">offset.cpp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">o before.ll</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">clang</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">++</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">std</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">+17</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">S </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">emit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">llvm </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">O1 choose</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">offset.cpp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">o after.ll</span></span></code></pre></div><p>機械語を格納したオブジェクトファイルでは、別ファイルで定義される関数やデータへの参照をリンカーに渡します。<a href="/study/compilers/coff-relocations.html">COFFの再配置</a></p>`,20)])])}const E=i(t,[["render",p]]);export{g as __pageData,E as default};
